let data;
const SUPABASE_URL=window.INNER_OS_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY=window.INNER_OS_SUPABASE_PUBLISHABLE_KEY;
let supabaseClient=null, currentUser={id:"shared"}, cloudSaveTimer=null, cloudChannel=null, lastCloudUpdatedAt=null, cloudReady=false;
function showApp(){const shell=$("#appShell");if(shell)shell.hidden=false;const email=$("#accountEmail");if(email)email.textContent="Sync enabled";const status=$("#cloudStatus");if(status)status.textContent="Connecting…"}
async function cloudSaveNow(){if(!supabaseClient||!cloudReady)return false;const stamp=new Date().toISOString();data.__ascendSchemaVersion=DATA_SCHEMA_VERSION;const {error}=await supabaseClient.from("shared_tracker_state").upsert({id:1,data,updated_at:stamp},{onConflict:"id"});if(error){console.error("Cloud save failed",error);setSaveStatus("Cloud save failed — changes may exist only in this browser");toast("Cloud save failed. Check Supabase setup.");return false}lastCloudUpdatedAt=stamp;setSaveStatus("Synced to shared cloud");const last=$("#lastCloudSave");if(last)last.textContent=new Date(stamp).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"});return true}
function queueCloudSave(){if(!cloudReady||!supabaseClient)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(cloudSaveNow,700)}
function subscribeToCloud(){if(cloudChannel){supabaseClient.removeChannel(cloudChannel);cloudChannel=null}cloudChannel=supabaseClient.channel("shared-tracker-state").on("postgres_changes",{event:"*",schema:"public",table:"shared_tracker_state",filter:"id=eq.1"},payload=>{const row=payload.new;if(!row?.data||row.data.__ascendSchemaVersion!==DATA_SCHEMA_VERSION)return;const stamp=row.updated_at||"";if(stamp&&lastCloudUpdatedAt&&stamp<=lastCloudUpdatedAt)return;const incoming={...seed(),...row.data};if(JSON.stringify(incoming)!==JSON.stringify(data)){data=incoming;prefs={...PREF_DEFAULTS,...(data.preferences||{})};persistPrefs(false);try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){}renderAll();setSaveStatus("Synced changes from another browser")}lastCloudUpdatedAt=stamp||lastCloudUpdatedAt}).subscribe(status=>{if(status==="SUBSCRIBED")setSaveStatus("Shared cloud sync active")})}
async function initSharedCloud(){showApp();let resetSharedRow=false;if(!SUPABASE_URL||!SUPABASE_PUBLISHABLE_KEY||!window.supabase?.createClient){setSaveStatus("Supabase configuration missing — saved locally");renderAll();generateMission();return}supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});setSaveStatus("Loading shared cloud data…");const {data:row,error}=await supabaseClient.from("shared_tracker_state").select("data,updated_at").eq("id",1).maybeSingle();if(error){console.error("Cloud load failed",error);setSaveStatus("Cloud unavailable — saved locally");toast("Could not connect to shared cloud. Run supabase-setup.sql.");renderAll();generateMission();return}if(row?.data&&row.data.__ascendSchemaVersion===DATA_SCHEMA_VERSION){data={...seed(),...row.data};lastCloudUpdatedAt=row.updated_at||null}else if(!row){data=seed();const stamp=new Date().toISOString();const result=await supabaseClient.from("shared_tracker_state").insert({id:1,data,updated_at:stamp});if(result.error){console.error("Cloud initialization failed",result.error);setSaveStatus("Could not initialize shared cloud");renderAll();generateMission();return}lastCloudUpdatedAt=stamp}else{data=seed();lastCloudUpdatedAt=row.updated_at||null;resetSharedRow=true}cloudReady=true;if(resetSharedRow)await cloudSaveNow();prefs={...PREF_DEFAULTS,...(data.preferences||{})};persistPrefs(false);try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){}renderAll();generateMission();subscribeToCloud();setSaveStatus("Shared cloud sync active")}
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return seed();const parsed=JSON.parse(raw);if(parsed.__ascendSchemaVersion!==DATA_SCHEMA_VERSION)return seed();return {...seed(),...parsed,history:parsed.history||{},habits:parsed.habits||[],skills:parsed.skills||[],goals:parsed.goals||[],books:parsed.books||[],priorities:parsed.priorities||[],roadmap:parsed.roadmap||seed().roadmap,weekPlan:parsed.weekPlan||seed().weekPlan,deepSessions:parsed.deepSessions||[],experiments:parsed.experiments||[],knowledge:parsed.knowledge||[],future:parsed.future||seed().future,proof:parsed.proof||[],tasks:parsed.tasks||[],appUsage:parsed.appUsage||[],journalEntries:parsed.journalEntries||[],mentalResources:[]}}catch(e){return seed()}}
data=load();
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));setSaveStatus(cloudReady?"Saving to shared cloud…":"Saved locally");queueCloudSave()}catch(e){setSaveStatus("Storage unavailable — export a backup");toast("Could not save. Export a backup.")}}
function setSaveStatus(s){const el=$("#reflectionSaved");if(el)el.textContent=s}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2300)}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function dateLabel(d){return d.toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"})}
function checkedToday(){return data.history[today()]||[]}
function setChecked(id,on){const k=today();const set=new Set(data.history[k]||[]);on?set.add(id):set.delete(id);data.history[k]=[...set];save();renderAll()}
function habitRate(days=7){let total=0,done=0;for(let i=0;i<days;i++){const d=new Date();d.setDate(d.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;const completed=new Set(data.history[key]||[]);total+=data.habits.length;done+=data.habits.filter(h=>completed.has(h.id)).length}return total?Math.round(done/total*100):0}
function renderOverview(){
 const checked=new Set(checkedToday());const hs=$("#habitStat"),hb=$("#habitBar");if(hs)hs.innerHTML=`${data.habits.filter(h=>checked.has(h.id)).length}<span class="stat-denom"> / ${data.habits.length}</span>`;if(hb)hb.style.width=(data.habits.length?data.habits.filter(h=>checked.has(h.id)).length/data.habits.length*100:0)+"%";
 const ss=$("#skillStat"),ssub=$("#skillSub");if(ss)ss.innerHTML=`${data.skills.length}<span class="stat-denom"> tracked</span>`;if(ssub)ssub.textContent=data.skills.length?`${Math.round(data.skills.reduce((s,x)=>s+x.level,0)/(data.skills.length*5)*100)}% average self-assessed level.`:"Add your first skill.";
 const gs=$("#goalStat"),gsub=$("#goalSub");if(gs)gs.textContent=data.goals.filter(g=>g.status!=="DONE").length;if(gsub)gsub.textContent=`${data.goals.filter(g=>g.status==="DONE").length} completed · ${data.goals.length} total`;const bs=$("#bookStat");if(bs)bs.textContent=data.books.length;
 const pl=$("#priorityList");if(pl)pl.innerHTML=data.priorities.length?data.priorities.map(p=>`<div class="priority-row ${p.done?"done":""}"><input class="check priority-check" type="checkbox" data-id="${p.id}" ${p.done?"checked":""} aria-label="Complete ${esc(p.text)}"><span class="priority-text">${esc(p.text)}</span><button class="delete-small priority-delete" data-id="${p.id}" aria-label="Delete task">×</button></div>`).join(""):`<div class="empty-state">No priorities yet. Add one meaningful task below.</div>`;
 renderChart($("#weekChart"),false);
}
function renderChart(el,large){if(!el)return;const values=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;const done=new Set(data.history[key]||[]);const n=data.habits.filter(h=>done.has(h.id)).length;values.push({label:d.toLocaleDateString(undefined,{weekday:"short"}).slice(0,2),value:data.habits.length?Math.round(n/data.habits.length*100):0,count:n})}
 el.innerHTML=values.map(v=>`<div class="day-column"><span class="day-value">${v.value}%</span><div class="bar-track"><div class="day-bar" style="height:${v.value}%"></div></div><span class="day-label">${v.label}</span></div>`).join("");
}
function renderSecurity(){$("#skillsList").innerHTML=data.skills.length?data.skills.map(s=>`<article class="skill-card"><div><h3 class="entry-title">${esc(s.name)}</h3><p class="entry-desc">${esc(s.desc||"")}</p><div class="entry-actions"><button class="small-action edit-skill" data-id="${s.id}">Edit details</button><button class="small-action danger delete-skill" data-id="${s.id}">Delete</button></div></div><div class="skill-controls"><input type="range" min="0" max="5" step="1" value="${s.level}" data-id="${s.id}" class="skill-range" aria-label="${esc(s.name)} level"><span class="level-label">${["NEW","EXPLORING","BASIC","PRACTICING","CAPABLE","STRONG"][s.level]}</span></div></article>`).join(""):`<div class="empty-state"><strong>No skills added yet.</strong>Add the first skill you want to develop.</div>`}
function renderHabits(){const checked=new Set(checkedToday());$("#habitDateHeading").textContent=dateLabel(new Date());$("#habitsList").innerHTML=data.habits.length?data.habits.map(h=>`<article class="habit-card ${checked.has(h.id)?"checked":""}"><input class="check habit-check" type="checkbox" data-id="${h.id}" ${checked.has(h.id)?"checked":""} aria-label="Mark ${esc(h.name)} complete"><div class="habit-main"><div class="habit-name">${esc(h.name)}</div><div class="habit-tag">${esc(h.tag||"DAILY PRACTICE")}</div></div><button class="small-action edit-habit" data-id="${h.id}">Edit</button><button class="delete-small delete-habit" data-id="${h.id}" aria-label="Delete habit">×</button></article>`).join(""):`<div class="empty-state"><strong>A clean slate.</strong>Add a habit you want to make consistent.</div>`;
 const n=data.habits.filter(h=>checked.has(h.id)).length;$("#habitSummary").textContent=`${n} of ${data.habits.length} completed`;$("#habitEncouragement").textContent=n===data.habits.length&&n?"All commitments kept today.":"Progress beats perfection."}
function renderGoals(){$("#goalsList").innerHTML=data.goals.length?data.goals.map(g=>`<article class="goal-card"><div class="goal-top"><div><div class="goal-category">${esc(g.category||"PERSONAL GOAL")}</div><h3 class="entry-title" style="margin-top:8px">${esc(g.title)}</h3></div><span class="goal-deadline">${g.deadline?esc(g.deadline):"NO DEADLINE"}</span></div><p class="goal-description">${esc(g.description||"")}</p><div><div class="goal-progress-head"><span>PROGRESS</span><span>${g.progress}%</span></div><div class="goal-progress"><div style="width:${g.progress}%"></div></div></div><div class="goal-actions"><span class="goal-status">${g.status==="DONE"?"COMPLETED":"IN PROGRESS"}</span><div class="entry-actions"><button class="small-action edit-goal" data-id="${g.id}">Edit</button><button class="small-action danger delete-goal" data-id="${g.id}">Delete</button></div></div></article>`).join(""):`<div class="empty-state"><strong>No goals defined.</strong>Give one important ambition a clear next step.</div>`}
function renderBooks(){$("#booksList").innerHTML=data.books.length?data.books.map(b=>`<article class="book-card"><div class="book-spine">READ / THINK</div><div class="book-info"><h3 class="entry-title">${esc(b.title)}</h3><p class="entry-desc">${esc(b.author||"Author not added")}</p><span class="book-status">${esc(b.status||"TO READ")}</span>${b.note?`<p class="entry-desc" style="margin-top:10px">${esc(b.note)}</p>`:""}<div class="entry-actions"><button class="small-action edit-book" data-id="${b.id}">Edit</button><button class="small-action danger delete-book" data-id="${b.id}">Remove</button></div></div></article>`).join(""):`<div class="empty-state"><strong>Your shelf is open.</strong>Add a book, then record what it made you question.</div>`}
function renderAnalytics(){$("#analyticsRate").textContent=habitRate()+"%";const done=data.goals.filter(g=>g.status==="DONE").length;$("#analyticsGoals").textContent=(data.goals.length?Math.round(done/data.goals.length*100):0)+"%";$("#analyticsSkills").textContent=(data.skills.length?Math.round(data.skills.reduce((s,x)=>s+x.level,0)/(data.skills.length*5)*100):0)+"%";renderChart($("#analyticsChart"),true);const rate=habitRate();$("#insightTitle").textContent=rate>=75?"Your consistency is taking shape.":rate>=40?"Build on the days you did show up.":"Make the next step smaller.";$("#insightText").textContent=rate>=75?"Protect the routine, and raise difficulty only when the current level feels repeatable.":rate>=40?"Look for friction on missed days. Reduce setup time and make the first action obvious.":"Choose one or two non-negotiable habits for the next week. A smaller plan you repeat beats an ambitious plan you avoid."}
function renderMind(){const grid=$("#problemGrid");if(!grid)return;grid.innerHTML=mindProblems.map(p=>`<button class="problem-card" data-problem="${p.id}"><span class="problem-icon">${p.icon}</span><span class="problem-tag">${p.tag}</span><strong>${p.title}</strong><span class="problem-open">OPEN PROTOCOL ↗</span></button>`).join("")}
function showProtocol(id){const p=mindProblems.find(x=>x.id===id);if(!p)return;const panel=$("#solutionPanel");panel.innerHTML=`<div class="solution-kicker">YOUR RESET PROTOCOL / ${p.tag}</div><div class="solution-layout"><div class="solution-lead"><div class="solution-icon">${p.icon}</div><h3>${p.title}</h3><p>${p.why}</p><div class="self-talk"><span>READ THIS TO YOURSELF</span><p>“${p.script}”</p><button class="small-action copy-script" data-script="${esc(p.script)}">Copy reminder</button></div></div><div class="solution-actions"><div class="eyebrow">THE NEXT 10 MINUTES</div><h4>Do this, in order.</h4>${p.steps.map((step,i)=>`<div class="protocol-step"><span>0${i+1}</span><p>${step}</p></div>`).join("")}<button class="primary-button start-protocol" data-task="${esc(p.steps[0])}">Make step one today's priority ↗</button></div></div>`;panel.scrollIntoView({behavior:"smooth",block:"start"})}
