function playFocusEndSound(){
try { const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C();const gain=ctx.createGain();const osc=ctx.createOscillator();const volume=(Number(prefs.focusVolume)||55)/100;gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.18*volume,ctx.currentTime+.04);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+1.2);osc.type="sine";osc.frequency.setValueAtTime(660,ctx.currentTime);osc.frequency.setValueAtTime(880,ctx.currentTime+.25);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+1.25);osc.onended=()=>ctx.close(); }catch(e){toast("Sound was blocked by the browser. Keep the page open and interact with it first.")}
}
