function setupPreferences(){const ids={appearanceTheme:"theme",prefTaskReminders:"taskReminders",quietStart:"quietStart",quietEnd:"quietEnd",prefOverdueAlerts:"overdueAlerts",startupAlertMode:"startupAlertMode",defaultFocusLength:"defaultFocusLength",defaultBreakLength:"defaultBreakLength",prefFocusNotify:"focusNotify",prefFocusSound:"focusSound",prefFocusVolume:"focusVolume"};persistPrefs();Object.entries(ids).forEach(([id,key])=>{const el=$("#"+id);if(!el)return;el.addEventListener("change",()=>{prefs[key]=el.type==="checkbox"?el.checked:(el.type==="range"?Number(el.value):(["defaultFocusLength","defaultBreakLength","focusVolume"].includes(key)?Number(el.value):el.value));persistPrefs();if(key==="defaultFocusLength"&&!focusRunning){focusMinutes=Number(prefs.defaultFocusLength);focusRemaining=focusMinutes*60;renderTimer();$$ (".timer-preset").forEach(b=>b.classList.toggle("active",Number(b.dataset.minutes)===focusMinutes))}if(key==="theme")toast(prefs.theme==="black"?"Pure-black theme applied.":"Graphite theme applied.");else toast("Preference saved.")})})}
