function isQuietTime(now=new Date()){const start=prefs.quietStart||"22:00",end=prefs.quietEnd||"06:00",current=now.getHours()*60+now.getMinutes(),a=Number(start.slice(0,2))*60+Number(start.slice(3)),b=Number(end.slice(0,2))*60+Number(end.slice(3));if(a===b)return false;return a<b?(current>=a&&current<b):(current>=a||current<b)}
