function renderUsage(){const entries=data.appUsage||[],now=today(),cut=new Date();cut.setDate(cut.getDate()-6);const cutoff=`${cut.getFullYear()}-${String(cut.getMonth()+1).padStart(2,"0")}-${String(cut.getDate()).padStart(2,"0")}`;const todayMin=entries.filter(x=>x.date===now).reduce((n,x)=>n+(+x.minutes||0),0),week=entries.filter(x=>x.date>=cutoff&&x.date<=now),weekMin=week.reduce((n,x)=>n+(+x.minutes||0),0),totals={};week.forEach(x=>totals[x.app]=(totals[x.app]||0)+(+x.minutes||0));const top=Object.entries(totals).sort((a,b)=>b[1]-a[1])[0];const put=(id,value)=>{const el=$(id);if(el)el.textContent=value};put("usageTodayTotal",`${todayMin} min`);put("usageWeekTotal",`${weekMin} min`);put("usageTopApp",top?.[0]||"—");put("usageTopMinutes",top?`${top[1]} min logged this week`:"Log your first session");const patterns=$("#usagePatterns");if(patterns){if(!week.length)patterns.innerHTML='<div class="empty-state">Log a few sessions to start seeing patterns.</div>';else{const triggers={},effects={};week.forEach(x=>{triggers[x.trigger]=(triggers[x.trigger]||0)+(+x.minutes||0);effects[x.effect]=(effects[x.effect]||0)+1});const trigger=Object.entries(triggers).sort((a,b)=>b[1]-a[1])[0],effect=Object.entries(effects).sort((a,b)=>b[1]-a[1])[0];patterns.innerHTML=`<article class="usage-pattern"><span class="eyebrow">MOST-LOGGED APP</span><strong>${esc(top?.[0]||"—")}</strong><p>${top?`${top[1]} minutes across the last seven days.`:"No app data yet."}</p></article><article class="usage-pattern"><span class="eyebrow">COMMON TRIGGER BY TIME</span><strong>${esc(trigger?.[0]||"Not enough data")}</strong><p>${trigger?`${trigger[1]} minutes were logged with this trigger. This is a self-reported association, not proof of cause.`:"Log the reason you opened an app."}</p></article><article class="usage-pattern"><span class="eyebrow">MOST-RECORDED AFTER-EFFECT</span><strong>${esc(effect?.[0]||"—")}</strong><p>${effect?`${effect[1]} session${effect[1]===1?"":"s"} marked this feeling.`:"Record how you felt after use."}</p></article>`}}const list=$("#usageLogList");if(list)list.innerHTML=entries.length?[...entries].sort((a,b)=>(b.date+b.createdAt).localeCompare(a.date+a.createdAt)).slice(0,40).map(x=>`<article class="usage-log-row"><div><strong>${esc(x.app)}</strong><p>${esc(x.trigger||"No trigger recorded")} · ${esc(x.effect||"No effect recorded")}${x.note?`<br>${esc(x.note)}`:""}</p><small>${esc(x.date)} · ${+x.minutes||0} min</small></div><button class="small-action danger delete-usage" data-id="${esc(x.id)}" aria-label="Delete usage entry">Remove</button></article>`).join(""):'<div class="empty-state">No usage records yet. Add your first session above.</div>'}
function renderJournal(){const list=$("#journalList"),entries=data.journalEntries||[];const count=$("#journalCount");if(count)count.textContent=`${entries.length} ENTR${entries.length===1?"Y":"IES"}`;if(list)list.innerHTML=entries.length?[...entries].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(x=>`<article class="journal-entry"><div class="journal-entry-head"><div><span class="eyebrow">${esc(x.mood||"REFLECTION")}</span><h3>${esc(x.title||"Untitled reflection")}</h3></div><small>${new Date(x.createdAt).toLocaleString([], {dateStyle:"medium",timeStyle:"short"})}</small></div><p>${esc(x.body).replace(/\n/g,"<br>")}</p>${x.tags?`<div class="journal-tags">${x.tags.split(",").map(t=>`<span>${esc(t.trim())}</span>`).join("")}</div>`:""}<button class="small-action danger delete-journal" data-id="${esc(x.id)}">Delete entry</button></article>`).join(""):'<div class="empty-state">Your journal is empty. Start with one honest paragraph.</div>'}
function renderAll(){renderOverview();renderSecurity();renderHabits();renderGoals();renderBooks();renderAnalytics();renderMind();renderRoadmap();renderWeekPlan();renderTimer();renderDeepSessions();renderExperiments();renderKnowledge();renderFuture();renderUsage();renderJournal();greeting();renderNewSections()}
function showTaskAlert(){
 const backdrop=$("#taskAlertBackdrop"),list=$("#taskAlertList");if(!backdrop||!list)return;
 const now=new Date(),soon=new Date(now.getTime()+20*60000);const candidates=[];
 const add=(t,kind)=>{if(!t||t.done)return;const date=t.date||today(),time=t.time;if(!time)return;const due=new Date(`${date}T${time}:00`);if(Number.isNaN(due.getTime()))return;if(due<now|| (due>=now&&due<=soon))candidates.push({title:t.text||t.name||"Untitled task",due,kind,overdue:due<now});};
 (data.priorities||[]).forEach(t=>add(t,"Priority"));(data.tasks||[]).forEach(t=>add(t,"Task"));
 candidates.sort((a,b)=>a.due-b.due);
 if(prefs.startupAlertMode==="never")return;const filtered=prefs.overdueAlerts?candidates:candidates.filter(t=>!t.overdue);if(!filtered.length)return;if(prefs.startupAlertMode==="daily"){const dayKey="ascend.taskAlert.lastShown";if(localStorage.getItem(dayKey)===today())return;localStorage.setItem(dayKey,today())}
 list.innerHTML=filtered.map(t=>`<article class="task-alert-item ${t.overdue?"overdue":"due-soon"}"><span class="task-alert-kind">${t.overdue?"OVERDUE":t.kind.toUpperCase()}</span><strong>${esc(t.title)}</strong><small>${t.overdue?`Was due ${t.due.toLocaleString([], {weekday:"short",hour:"numeric",minute:"2-digit"})}`:`Due ${t.due.toLocaleTimeString([], {hour:"numeric",minute:"2-digit"})}`}</small></article>`).join("");
 backdrop.hidden=false;document.body.classList.add("modal-open");
}
function closeTaskAlert(){const b=$("#taskAlertBackdrop");if(b)b.hidden=true;document.body.classList.remove("modal-open")}
function showView(name){window.AscendInsights&&AscendInsights.onView(name);document.body.dataset.mode=name;$$(".view").forEach(v=>v.classList.toggle("active",v.id==="view-"+name));$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===name));$("#crumbName").textContent=({overview:"HOME",learn:"LEARN",practice:"PRACTICE",usage:"APP PATTERNS",journal:"JOURNAL",mental:"MENTAL SPACE",settings:"SETTINGS",security:"CYBERSECURITY",habits:"SELF-CARE HABITS",goals:"LONG-TERM GOALS",library:"BOOKS & PHILOSOPHY",analytics:"REVIEW",motivation:"MIND & MOTIVATION",roadmap:"SKILL ROADMAP",deepwork:"DEEP WORK",experiments:"PERSONAL EXPERIMENTS",knowledge:"KNOWLEDGE VAULT",future:"FUTURE SELF"})[name]||name.toUpperCase();window.scrollTo({top:0,behavior:"smooth"})}
