document.addEventListener("click",e=>{const tf=e.target.closest("[data-task-filter]");if(tf){$$ ("[data-task-filter]").forEach(x=>x.classList.toggle("active",x===tf));renderTodayTasks()}const go=e.target.closest("[data-go]");if(go)showView(go.dataset.go);const td=e.target.closest(".task-delete");if(td){if(td.dataset.priority==="true")data.priorities=data.priorities.filter(x=>x.id!==td.dataset.taskId);else data.tasks=data.tasks.filter(x=>x.id!==td.dataset.taskId);save();renderAll()}const md=e.target.closest(".mental-delete");if(md&&confirm("Remove this resource?")){data.mentalResources=data.mentalResources.filter(x=>x.id!==md.dataset.id);save();renderMental()}});
