const alertClose=$("#taskAlertClose"),alertDone=$("#taskAlertDone"),alertBackdrop=$("#taskAlertBackdrop");if(alertClose)alertClose.onclick=closeTaskAlert;if(alertDone)alertDone.onclick=closeTaskAlert;if(alertBackdrop)alertBackdrop.addEventListener("click",e=>{if(e.target===alertBackdrop)closeTaskAlert()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeTaskAlert()});
