const dlg=$("#editDialog");let editType=null,editId=null;
function field(label,name,value="",type="text",placeholder=""){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}"></div>`}
function area(label,name,value="",placeholder=""){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`}
function selectField(label,name,value,opts){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${opts.map(o=>`<option ${value===o?"selected":""}>${esc(o)}</option>`).join("")}</select></div>`}
function openEditor(type,title,item){editType=type;editId=item?.id||null;$("#dialogTitle").textContent=title;$("#dialogEyebrow").textContent=type.toUpperCase()+" ENTRY";let f="";
 if(type==="skill")f=field("Skill name","name",item?.name||"")+area("Description","desc",item?.desc||"")+`<div class="field"><label for="f-level">SELF-ASSESSED LEVEL (0–5)</label><select id="f-level" name="level">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${+(item?.level??0)===n?"selected":""}>${n} — ${["New","Exploring","Basic","Practicing","Capable","Strong"][n]}</option>`).join("")}</select></div>`;
 if(type==="habit")f=field("Habit name","name",item?.name||"")+field("Category tag","tag",item?.tag||"SELF-CARE")+field("Reminder time","time",item?.time||"07:00","time")+`<div class="field"><label><input type="checkbox" name="reminder" value="yes" ${item?.reminder===false?"":"checked"}> Enable reminder</label></div>`;
 if(type==="goal")f=field("Goal title","title",item?.title||"")+`<div class="field-row">${field("Category","category",item?.category||"PERSONAL GROWTH")}${field("Target date","deadline",item?.deadline||"","date")}</div>`+area("Description","description",item?.description||"")+`<div class="field"><label for="f-progress">PROGRESS (0–100)</label><input id="f-progress" name="progress" type="number" min="0" max="100" value="${item?.progress??0}"></div>`+selectField("Status","status",item?.status||"ACTIVE",["ACTIVE","DONE"]);
 if(type==="book")f=field("Book title","title",item?.title||"")+field("Author","author",item?.author||"")+selectField("Reading status","status",item?.status||"TO READ",["TO READ","READING","COMPLETED","ON HOLD"])+area("Note / key idea","note",item?.note||"");
 $("#dialogFields").innerHTML=f;dlg.showModal()}
$("#editorForm").addEventListener("submit",e=>{if(e.submitter?.value!=="save")return;e.preventDefault();const fd=new FormData(e.currentTarget);const v=Object.fromEntries(fd.entries());let list=data[({skill:"skills",habit:"habits",goal:"goals",book:"books"})[editType]];let obj;
 if(editType==="skill")obj={name:v.name.trim(),desc:v.desc.trim(),level:Math.max(0,Math.min(5,+v.level||0))};
 if(editType==="habit")obj={name:v.name.trim(),tag:v.tag.trim()||"SELF-CARE",time:v.time||"07:00",reminder:v.reminder==="yes"};
 if(editType==="goal")obj={title:v.title.trim(),category:v.category.trim()||"PERSONAL GOAL",deadline:v.deadline,description:v.description.trim(),progress:Math.max(0,Math.min(100,+v.progress||0)),status:v.status}; 
 if(editType==="book")obj={title:v.title.trim(),author:v.author.trim(),status:v.status,note:v.note.trim()};
 const required=obj.name??obj.title;if(!required){toast("Please enter a name or title.");return}
 if(editId){const i=list.findIndex(x=>x.id===editId);if(i>=0)list[i]={...list[i],...obj}}else list.push({id:uid(),...obj});
 if(editType==="goal"){const g=list.find(x=>x.id===(editId||list[list.length-1].id));if(g&&g.progress===100)g.status="DONE"}
 save();dlg.close();renderAll();toast(editId?"Entry updated":"Entry added")});
